--
-- Name: enercal_comparison_view; Type: VIEW; Schema: public; Owner: app_user
--

CREATE VIEW public.enercal_comparison_view AS
 SELECT d.document_id,
    m.case_ref,
    d.filename,
    p.page_number AS source_page,
    t.technology_role,
    max(c.raw_value) FILTER (WHERE (c.field_name = (t.technology_role || '_elevator_technology'::text))) AS elevator_technology,
    max(c.numeric_value) FILTER (WHERE (c.field_name = (t.technology_role || '_annual_energy_consumption'::text))) AS annual_energy_consumption_kwh_year,
    max(c.numeric_value) FILTER (WHERE (c.field_name = (t.technology_role || '_annual_regenerative_energy'::text))) AS annual_regenerative_energy_kwh_year,
    max(c.numeric_value) FILTER (WHERE (c.field_name = (t.technology_role || '_annual_electricity_expenditure'::text))) AS annual_electricity_expenditure_bhd_year,
    max(c.numeric_value) FILTER (WHERE (c.field_name = (t.technology_role || '_lifetime_electricity_expenditure'::text))) AS lifetime_electricity_expenditure_bhd,
    max(c.numeric_value) FILTER (WHERE (c.field_name = (t.technology_role || '_operational_co2e'::text))) AS operational_co2e_kg_lifetime_20_years,
    max(c.numeric_value) FILTER (WHERE (c.field_name = (t.technology_role || '_embodied_co2e'::text))) AS embodied_co2e_kg,
    max(c.numeric_value) FILTER (WHERE (c.field_name = 'reported_energy_saving_percent'::text)) AS reported_energy_saving_percent,
    max(c.numeric_value) FILTER (WHERE (c.field_name = 'calculated_energy_saving_percent'::text)) AS calculated_energy_saving_percent,
    r.revision_no,
    (r.review_status)::text AS review_status
   FROM (((((public.source_documents d
     JOIN public.modernisation_cases m ON ((m.case_id = d.case_id)))
     JOIN public.extraction_revisions r ON (((r.document_id = d.document_id) AND (r.revision_no = ( SELECT max(r2.revision_no) AS max
           FROM public.extraction_revisions r2
          WHERE (r2.document_id = d.document_id))))))
     JOIN public.extraction_candidates c ON ((c.extraction_revision_id = r.revision_id)))
     JOIN public.document_pages p ON (((p.page_id = c.page_id) AND (p.document_id = d.document_id))))
     CROSS JOIN ( VALUES ('existing'::text), ('proposed'::text)) t(technology_role))
  GROUP BY d.document_id, m.case_ref, d.filename, p.page_number, t.technology_role, r.revision_no, r.review_status
 HAVING (max(c.raw_value) FILTER (WHERE (c.field_name = (t.technology_role || '_elevator_technology'::text))) IS NOT NULL);


