CREATE VIEW public.enercal_approved_comparison_view AS
 SELECT v.document_id,
    v.case_ref,
    v.filename,
    v.source_page,
    v.technology_role,
    v.elevator_technology,
    v.annual_energy_consumption_kwh_year,
    v.annual_regenerative_energy_kwh_year,
    v.annual_electricity_expenditure_bhd_year,
    v.lifetime_electricity_expenditure_bhd,
    v.operational_co2e_kg_lifetime_20_years,
    v.embodied_co2e_kg,
    v.reported_energy_saving_percent,
    v.calculated_energy_saving_percent,
    v.revision_no,
    (r.review_status)::text AS review_status
   FROM (public.enercal_comparison_view v
     JOIN public.extraction_revisions r ON (((r.document_id = v.document_id) AND (r.revision_no = v.revision_no))))
  WHERE (((r.review_status)::text = 'approved'::text) AND (r.revision_no = ( SELECT max(r2.revision_no) AS max
           FROM public.extraction_revisions r2
          WHERE (r2.document_id = r.document_id))) AND (( SELECT count(*) AS count
           FROM public.extraction_candidates c
          WHERE (c.extraction_revision_id = r.revision_id)) = 16) AND (( SELECT count(DISTINCT c.field_name) AS count
           FROM public.extraction_candidates c
          WHERE (c.extraction_revision_id = r.revision_id)) = 16) AND (( SELECT count(DISTINCT c.page_id) AS count
           FROM public.extraction_candidates c
          WHERE (c.extraction_revision_id = r.revision_id)) = 1));


