--
-- Name: enercal_crosscheck_summary_view; Type: VIEW; Schema: public; Owner: app_user
--

CREATE VIEW public.enercal_crosscheck_summary_view AS
 SELECT document_id,
    count(*) AS total_checks,
    count(*) FILTER (WHERE (check_status = 'PASS'::text)) AS passed,
    count(*) FILTER (WHERE (check_status = 'REVIEW'::text)) AS needs_review,
    count(*) FILTER (WHERE (check_status = 'MISSING'::text)) AS missing
   FROM public.enercal_crosschecks_view
  GROUP BY document_id;


